import sys
from stackprinter.formatting import format_stack_from_frame
def inner():
    return sys._getframe(0)
def outer():
    return inner()
fr = outer()
out = format_stack_from_frame(fr)
print('frame_sequence', 'outer' in out and 'inner' in out)
assert out.index('outer') < out.index('inner'), out[-1500:]
